package com.rekluzlabs.makokolorize.mlimport ai.onnxruntime.OnnxTensorimport ai.onnxruntime.OrtEnvironmentimport ai.onnxruntime.OrtSessionimport ai.onnxruntime.TensorInfoimport android.util.Logimport java.nio.FloatBufferclass ScunetModel(modelPath: String) : AutoCloseable {    private val env: OrtEnvironment = OrtEnvironment.getEnvironment()    private val session: OrtSession = env.createSession(modelPath, OrtSession.SessionOptions())    val inputName: String    val inputChannels: Int    init {        val info = session.inputInfo.values.first()        val tensorInfo = info.info as TensorInfo        val shape = tensorInfo.shape        inputName = session.inputNames?.first() ?: throw IllegalStateException("No input name found")        inputChannels = if (shape.size >= 4 && shape[1].toInt() in 1..3) shape[1].toInt() else 3        Log.d("ScunetModel", "Model: inputName=$inputName, inputChannels=$inputChannels, shape=${shape.contentToString()}")    }    fun run(inputFloat: FloatArray, height: Int, width: Int): FloatArray {        val data: FloatArray = if (inputChannels == 1) {            val gray = FloatArray(height * width)            for (i in 0 until height * width) {                val r = inputFloat[i]                val g = inputFloat[height * width + i]                val b = inputFloat[2 * height * width + i]                gray[i] = 0.299f * r + 0.587f * g + 0.114f * b            }            gray        } else {            inputFloat        }        val shape = longArrayOf(1L, inputChannels.toLong(), height.toLong(), width.toLong())        val buffer = FloatBuffer.wrap(data)        val inputTensor = OnnxTensor.createTensor(env, buffer, shape)        inputTensor.use {            val inputs = mapOf(inputName to inputTensor)            session.run(inputs).use { outputs ->                val outputTensor = outputs[0] as OnnxTensor                return flattenOnnxOutput(outputTensor, height, width)            }        }    }    private fun flattenOnnxOutput(outputTensor: OnnxTensor, height: Int, width: Int): FloatArray {        Log.d("ScunetModel", "Output tensor info: ${outputTensor.info}")        val buf = outputTensor.floatBuffer        val result = FloatArray(buf.remaining())        buf.get(result)        Log.d("ScunetModel", "Output buffer size=${result.size}, expected=${3 * height * width}")        return result    }    override fun close() {        session.close()        // Do NOT close env — it is a shared singleton from OrtEnvironment.getEnvironment()    }}